package main

import (
	"flag"
	"fmt"
	"image"
	"image/color"
	"image/gif"
	"image/jpeg"
	"image/png"
	"math"
	"os"
	"strings"
)

func main() {
	w := flag.Int("w", 100)
	h := flag.Int("h", 100)
	out := flag.String("o", "out.png")
	pat := flag.String("p", "diag")
	flag.Parse()
	img := image.NewNRGBA(image.Rect(0, 0, *w, *h))
	switch *pat {
	case "diag":
		for y := 0; y < *h; y++ {
			for x := 0; x < *w; x++ {
				img.Set(x, y, color.RGBA{uint8(x * 255 / max(1,*w)), uint8(y * 255 / max(1,*h)), uint8((x+y)*255/max(1,*w+*h)), 255})
			}
		}
	case "flat":
		for y := 0; y < *h; y++ {
			for x := 0; x < *w; x++ {
				img.Set(x, y, color.RGBA{0x12, 0x34, 0x56, 255})
			}
		}
	case "grid":
		for y := 0; y < *h; y++ {
			for x := 0; x < *w; x++ {
				var c color.RGBA
				if x < *w/2 {
					if y < *h/2 {
						c = color.RGBA{255, 0, 0, 255}
					} else {
						c = color.RGBA{0, 255, 0, 255}
					}
				} else {
					if y < *h/2 {
						c = color.RGBA{0, 0, 255, 255}
					} else {
						c = color.RGBA{255, 255, 255, 255}
					}
				}
				img.Set(x, y, c)
			}
		}
	case "checker":
		for y := 0; y < *h; y++ {
			for x := 0; x < *w; x++ {
				c := color.RGBA{0,0,0,255}
				if (x/8+y/8)%2 == 0 {
					c = color.RGBA{255, 255, 255, 255}
				}
				img.Set(x, y, c)
			}
		}
	case "alpha":
		for y := 0; y < *h; y++ {
			for x := 0; x < *w; x++ {
				a := uint8(0)
				if x*2 < *w { a = uint8(x*255/ (*w/2+1)) }
				img.Set(x, y, color.RGBA{255, 0, 0, a})
			}
		}
	}
	f, _ := os.Create(*out)
	defer f.Close()
	switch {
	case strings.HasSuffix(*out, ".png"):
		png.Encode(f, img)
	case strings.HasSuffix(*out, ".jpg") || strings.HasSuffix(*out, ".jpeg"):
		jpeg.Encode(f, img, &jpeg.Options{Quality: 100})
	case strings.HasSuffix(*out, ".gif"):
		g.Encode(f, img)
	default:
		fmt.Println("unknown ext")
	}
}
