    g=a//8; x=a%8
    bg=G[(g,x)]
    exp=(premul8(200,a),premul8(60,a),premul8(110,a))
    tot+=1
    if tuple(bg)!=exp:
        bad+=1
        if bad<10: print('MISMATCH a=%d obs=%s exp=%s'%(a,tuple(bg),exp))
print('total',tot,'bad',bad)
EOF"}

