import sys
def premul8(c,a): return (c*257*a//255)>>8
rows=[l.split() for l in open('/tmp/t/matdata.txt')]
data={}
for r in rows:
    m=r[0]; a=int(r[1]); data.setdefault(m,[]).append((a,int(r[2]),int(r[3]),int(r[4])))
mattes={'000000':(0,0,0),'FFFFFF':(255,255,255),'102030':(16,32,48)}
srcs=(200,60,110)
for m,vals in data.items():
    M=mattes[m]
    print('=== matte',m)
    hyps=(
      ('H1 premul+premulM', lambda c,a: premul8(c,a)+premul8(M[0],255-a) if False else premul8(c,a)+premul8(1,1)),
    )
    def h1(c,a): return premul8(c,a)+premul8(0,0)
    tests=(
      ('H1 premul+premulM', lambda c,a: premul8(c,a)+premul8(M[0],255-a)),
      ('H2 combined16', lambda c,a: ((c*257*a + M[0]*257*(255-a))//255)>>8),
      ('H3 premul+floorM', lambda c,a: premul8(c,a)+M[0]*(255-a)//255),
      ('H4 premul+roundM', lambda c,a: premul8(c,a)+int(round(M[0]*(255-a)/255))),
      ('H5 premul+truncM', lambda c,a: premul8(c,a)+int(M[0]*(255-a)/255)),
      ('H6 allfloat', lambda c,a: int((c*a/255 + M[0]*(255-a)/255))),
      ('H7 premul+drawover', lambda c,a: premul8(c,a)+ (M[0]*((0xffff-a*257)*0x101)//0xffff)>>8),
    )
    for name,f in tests:
        bad=0
        for (a,R,Gr,B) in vals:
            exp=tuple(f(c,a) for c in srcs)
            if exp!=(R,Gr,B): bad+=1
        print('   %-24s bad=%d/%d'%(name,bad,len(vals)))
EOF"}

