import sys; sys.path.insert(0,'/tmp/t')
import pngio,proto,ansi,subprocess,random
def check(w,h,px,tc,tr,matte=(0,0,0),label=''):
    G=proto.grid3(w,h,px,tc,tr,matte)
    pngio.write_png('/tmp/t/vv.png',w,h,[p for row in px for p in row])
    r=subprocess.run(['/workspace/executable','-tc',str(tc),'-tr',str(tr),'-m','%02X%02X%02X'%matte,'/tmp/t/vv.png'],capture_output=True)
    if r.returncode!=0: return 'ERR '+r.stderr.decode().strip()
    real=ansi.parse(r.stdout)
    ndiff=0;maxd=0;first=None
    for i in range(tr):
        for j in range(tc):
            for k in (0,1):
                mv=tuple(proto.clip(v) for v in G[2*i+2+k][j]); rv=real[i][j][k+1]
                if mv!=rv:
                    ndiff+=1; d=max(abs(mv[ch]-rv[ch]) for ch in range(3))
                    if d>maxd: maxd=d
                    if first is None: first=(i,j,k,mv,rv)
    return (ndiff,maxd,first)
def batch():
    random.seed(7)
    tot=0;bad=0
    for matte in ((0,0,0),(255,255,255),(16,32,48),(255,0,0)):
      for nch in (3,4):
        for (w,h,tc,tr) in [(3,3,2,2),(6,7,4,5),(20,9,7,4),(9,20,4,8),(12,12,8,7),(100,100,80,22),(545,749,80,22),(7,7,7,7),(2,2,2,2)]:
            px=[[tuple(random.randrange(256) for _ in range(nch)) for x in range(w)] for y in range(h)]
            d=check(w,h,px,tc,tr,matte); tot+=1
            if isinstance(d,str) or d[0]: bad+=1; print('FAIL %s nch%d %dx%d tc%d tr%d:'%(str(matte),nch,w,h,tc,tr),str(d)[:200])
    print('cases',tot,'bad',bad)
if __name__=='__main__': batch()
EOF
