{"command": "cd /tmp/t && python3 - <<'EOF'
import sys; sys.path.insert(0,'/tmp/t')
import pngio,proto,random,math
from decimal import Decimal, getcontext
getcontext().prec=60
D=Decimal
random.seed(11)
w,h=3,3
rgb=[[tuple(random.randrange(256) for _ in range(3)) for x in range(w)] for y in range(h)]
def dsinc(x):
    if x==0: return D(1)
    return D(math.sin(math.pi*float(x)))/(D(math.pi)*x)
def dL3(x):
    ax=abs(x)
    if ax>=3: return D(0)
    return dsinc(x)*dsinc(x/D(3))
def dweights(srcN,dstN):
    scale=D(srcN)/D(dstN)
    fs=max(D(1),scale)
    radius=D(3)*fs
    out=[]
    for d in range(dstN):
        center=(D(d)+D('0.5'))*scale-D('0.5')
        j0=max(0,math.ceil(float(center-radius))); j1=min(srcN-1,math.floor(float(center+radius)))
        ws=[dL3((center-D(j))/fs) for j in range(j0,j1+1)]
        S=sum(ws)
        ws=[w/S for w in ws]
        out.append((j0,ws))
    return out
wh=dweights(w,2); wv=dweights(h,6)
mid=[]
for d in range(h):
    j0,ws=wv[d]
    row=[]
    for x in range(w):
        acc=[D(0)]*3
        for k in range(len(ws)):
            v=rgb[j0+k][x]
            for ch in range(3): acc[ch]+=ws[k]*D(v[ch])
        row.append(acc)
    mid.append(row)
def hrnd(v):
    if v<0: return 0
    if v>=256: return 255
    return int((v*2+1).to_integral_value(rounding='ROUND_FLOOR'))
midr=[[tuple(hrnd(mid[y][x][ch]) for ch in range(3)) for x in range(w)] for y in range(h)]
print('mid rounded:',midr)
for g in range(2,6):
    j0,ws=wv[g]
    for c in range(2):
        j0h,wsh=wh[c]
        acc=[D(0)]*3
        for k in range(len(ws)):
            hval=sum(wsh[kk]*D(midr[j0+k][j0h+kk][ch]) for kk in range(len(wsh)))
            acc=[acc[ch]+ws[k]*hval for ch in range(3)]
        print('g%d c%d = %s'%(g,c,[str(a)[:24] for a in acc]))
EOF"}

